using System.Net.Http; using System.Text.Json; namespace KeHoachDaNgoai.Services; public record WeatherInfo(string Description,double Min,double Max,int Rain,int Code); public class WeatherService { static readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(8)}; readonly string geo,forecast; public WeatherService(string g,string f){geo=g;forecast=f;} public async Task<WeatherInfo?> GetAsync(string place,DateTime date){string url=$"{geo}?name={Uri.EscapeDataString(place)}&count=1&language=vi&format=json"; using var g=JsonDocument.Parse(await http.GetStringAsync(url)); var arr=g.RootElement.GetProperty("results"); if(arr.GetArrayLength()==0)return null; var loc=arr[0]; string fu=$"{forecast}?latitude={loc.GetProperty("latitude").GetDouble().ToString(System.Globalization.CultureInfo.InvariantCulture)}&longitude={loc.GetProperty("longitude").GetDouble().ToString(System.Globalization.CultureInfo.InvariantCulture)}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&forecast_days=16"; using var f=JsonDocument.Parse(await http.GetStringAsync(fu)); var d=f.RootElement.GetProperty("daily"); var times=d.GetProperty("time"); int i=-1; for(int x=0;x<times.GetArrayLength();x++)if(times[x].GetString()==date.ToString("yyyy-MM-dd")){i=x;break;} if(i<0)return null; int code=d.GetProperty("weather_code")[i].GetInt32(); int rain=d.GetProperty("precipitation_probability_max")[i].GetInt32(); return new(Describe(code),d.GetProperty("temperature_2m_min")[i].GetDouble(),d.GetProperty("temperature_2m_max")[i].GetDouble(),rain,code); } static string Describe(int c)=>c==0?"Trời quang":c<=3?"Có mây":c==45||c==48?"Sương mù":(c>=51&&c<=67)||(c>=80&&c<=82)?"Mưa":c>=95&&c<=99?"Dông":"Không rõ"; }